const project = $('Load Project + Client').first().json;
const projectId = $('Receive Project').first().json.project_id;
const prevBriefingData = $('Load Existing Briefing').first().json;
const hasPrevBriefing = prevBriefingData && prevBriefingData.id && (prevBriefingData.version !== undefined && prevBriefingData.version !== null && prevBriefingData.version > 0);
const promptData = $('Load Agent Prompt').first().json;
// === STUDIO PROFILE INJECTION (B23) ===
const _studio = $('Load Studio Profile').first().json || {};
function _safeStudio(v){ if(v==null)return null; if(typeof v==='string'){try{return JSON.parse(v);}catch(e){return v;}} return v; }
const _id=_safeStudio(_studio.identity)||{},_tone=_safeStudio(_studio.tone)||{},_priorities=_safeStudio(_studio.priorities)||[],_redLines=_safeStudio(_studio.red_lines)||[],_checklist=_safeStudio(_studio.visit_checklist)||[],_jur=_safeStudio(_studio.jurisdiction)||{};
const _toneCli=_tone.clientes||{};
const _STUDIO_CONTEXT_LINES=[];
_STUDIO_CONTEXT_LINES.push('Trabajas para "'+(_id.nombre_estudio||'estudio')+'" en '+(_id.ciudad||'Espana')+', especializado en '+(((_id.ambito||[]).join(', '))||'arquitectura tecnica')+'.');
_STUDIO_CONTEXT_LINES.push('TONO con clientes: '+(_toneCli.formalidad||'cercano')+', '+(_toneCli.tecnicidad||'llano')+', '+(_toneCli.longitud||'conciso')+(_toneCli.tutea?'. Tutea por defecto.':'. Usa usted por defecto.')+(_toneCli.explica_terminos?' Explica terminos tecnicos entre parentesis.':''));
_STUDIO_CONTEXT_LINES.push('PRIORIDADES (orden estricto):');
(_priorities||[]).forEach(p=>{ _STUDIO_CONTEXT_LINES.push((p.orden||'?')+'. '+(p.prioridad||'')+(p.detalle?' - '+p.detalle:'')); });
_STUDIO_CONTEXT_LINES.push('LINEAS ROJAS (NUNCA hacer):');
(_redLines||[]).forEach(l=>{ _STUDIO_CONTEXT_LINES.push('- '+(l.texto||'')); });
_STUDIO_CONTEXT_LINES.push('JURISDICCION: '+(_jur.ccaa||'Espana')+'. Aplica normativa estatal (CTE, LOE, RD 1627/1997, REBT, RITE) + autonomica.');
const _STUDIO_CONTEXT = _STUDIO_CONTEXT_LINES.join('\n');
const _checklistExtra = (_checklist && _checklist.length>0) ? '\n\nCHECKLIST de open_questions a incluir si no estan resueltas en las notas: '+_checklist.map(c=>c.pregunta||'').filter(Boolean).join(' / ') : '';
const _baseSystemPrompt = (promptData && promptData.content)
  ? promptData.content
  : 'Eres el Agente de Briefing de un estudio de arquitectura tecnica. Convierte la informacion inicial del proyecto en un briefing estructurado. Responde EXCLUSIVAMENTE con un objeto JSON valido sin backticks ni texto adicional.';
const systemPrompt = _STUDIO_CONTEXT + _checklistExtra + '\n\n' + _baseSystemPrompt;
// === END STUDIO PROFILE INJECTION ===
const model = ((promptData && promptData.model_recommended) || 'gpt-4o').trim();
const temperature = (promptData && promptData.temperature !== null && promptData.temperature !== undefined) ? Number(promptData.temperature) : 0.2;
const nextVersion = hasPrevBriefing ? (prevBriefingData.version + 1) : 1;
const metadata = project.metadata || {};
const metaNotes = metadata.architect_intake_notes || metadata.notes || metadata.description || '';
const metaObservations = metadata.architect_observations || '';
const metaPreferences = metadata.client_stated_preferences || '';
const metaVisitDate = metadata.visit_date || '';
const budgetStr = project.budget_target ? project.budget_target + ' EUR' : 'No especificado';
const areaStr = project.property_area_m2 ? project.property_area_m2 + ' m2' : 'No especificada';
const locationParts = [project.location_address, project.location_city, project.location_province].filter(Boolean);
const locationStr = locationParts.length > 0 ? locationParts.join(', ') : 'No especificada';
const userParts = [
  'Genera el briefing estructurado para este proyecto.',
  '',
  'DATOS DEL PROYECTO:',
  '- Nombre: ' + (project.project_name || 'Sin nombre'),
  '- Tipo: ' + (project.project_type || 'No especificado'),
  '- Localizacion: ' + locationStr,
  '- Tipo de inmueble: ' + (project.property_type || 'No especificado'),
  '- Superficie aproximada: ' + areaStr,
  '- Presupuesto objetivo: ' + budgetStr + (project.budget_flexible ? ' (flexible)' : ' (ajustado)'),
  '- Urgencia: ' + (project.urgency || 'normal'),
  '',
  'DATOS DEL CLIENTE:',
  '- Nombre: ' + (project.client_name || 'Sin nombre'),
  '- Notas del cliente: ' + (project.client_notes || 'Sin notas'),
  '',
  'NOTAS DEL ARQUITECTO TRAS VISITA:' + (metaVisitDate ? ' (' + metaVisitDate + ')' : ''),
  metaNotes || 'Sin notas del arquitecto',
  '',
  'OBSERVACIONES TECNICAS DEL ARQUITECTO (patologias, oportunidades, estado del inmueble):',
  metaObservations || 'Sin observaciones registradas',
  '',
  'PATOLOGIAS DETECTADAS POR agent_pathology (' + ((project.pathology_findings || []).length) + '):',
  ((project.pathology_findings || []).length === 0 ? '  (sin patologias registradas todavia)' : (project.pathology_findings || []).map(function(p) {
    var cost = (p.cost_min || p.cost_max) ? ' [estimado ' + (p.cost_min || 0) + '-' + (p.cost_max || 0) + 'eur]' : '';
    var safety = p.affects_safety ? ' [AFECTA SEGURIDAD]' : '';
    return '  - [' + (p.severity || '?').toUpperCase() + '] ' + (p.type || '?') + ': ' + (p.description || '?') + safety + cost + (p.recommended_action ? ' → ' + p.recommended_action : '');
  }).join('\n')),
  '',
  'PREFERENCIAS TRANSMITIDAS POR EL CLIENTE:',
  metaPreferences || 'Sin preferencias registradas'
];

try {
  const sim = $('Search Similar Cases').first().json;
  const cases = (sim && sim.similar_cases) ? sim.similar_cases : [];
  if (cases.length > 0) {
    userParts.push('');
    userParts.push('CASOS SIMILARES DE PROYECTOS ANTERIORES (memoria del estudio):');
    cases.slice(0, 3).forEach((c, i) => {
      userParts.push((i+1) + '. ' + (c.summary || '?') + ' [similitud ' + Math.round((c.similarity||0) * 100) + '%, ' + (c.area_m2||'?') + 'm2, ' + (c.location_zone||'?') + ']');
      const lessons = c.lessons_learned ? (typeof c.lessons_learned === 'string' ? JSON.parse(c.lessons_learned) : c.lessons_learned) : [];
      lessons.slice(0, 2).forEach(l => userParts.push('   - ' + (l.lesson || JSON.stringify(l)).substring(0, 150)));
    });
    userParts.push('Aprovecha estas lecciones al detectar constraints y proponer open_questions.');
  }
} catch(e) {}

const _userPartsExtended = [
];
if (hasPrevBriefing && prevBriefingData.status === 'revision_requested') {
  userParts.push('');
  userParts.push('BRIEFING ANTERIOR RECHAZADO (esta es la revision ' + nextVersion + '):');
  userParts.push('Resumen previo: ' + (prevBriefingData.summary || '').substring(0, 400));
  userParts.push('Corrige y mejora el briefing anterior basandote en el contexto disponible.');
}
userParts.push('');
userParts.push('Responde con el JSON estructurado del briefing.');
const userPrompt = userParts.join('\n');
return [{ json: { agent_name: 'agent_briefing',
  project_id: projectId,
  project_name: project.project_name,
  client_name: project.client_name,
  client_email: project.client_email || null,
  next_version: nextVersion,
  prompt_system: systemPrompt,
  prompt_user: userPrompt,
  model: model,
  temperature: temperature
} }];

const llmResult = $input.first().json;
const preparedData = $('Prepare LLM Payload').first().json;
let responseText = (llmResult.text || llmResult.response_text || llmResult.content || '').trim();
if (responseText.startsWith('```')) {
  responseText = responseText.replace(/^```[a-z]*\n?/, '').replace(/\n?```$/, '').trim();
}
let parsed;
try {
  parsed = JSON.parse(responseText);
} catch(e) {
  // Intentar extraer JSON embebido con regex
  const m = responseText.match(/\{[\s\S]*\}/);
  if (m) {
    try { parsed = JSON.parse(m[0]); } catch(e2) { parsed = null; }
  } else {
    parsed = null;
  }
}
const isValid = parsed && typeof parsed.summary === 'string';
if (!isValid) {
  parsed = {
    summary: 'Error al procesar respuesta del LLM. Revisar manualmente. Respuesta: ' + responseText.substring(0, 200),
    client_needs: [],
    objectives: [],
    constraints: [],
    style_preferences: {},
    rooms_affected: [],
    missing_info: ['La respuesta del LLM no fue JSON valido'],
    open_questions: []
  };
}
return [{ json: {
  project_id: preparedData.project_id,
  project_name: preparedData.project_name,
  client_name: preparedData.client_name,
  client_email: preparedData.client_email,
  next_version: preparedData.next_version,
  summary: parsed.summary || '',
  client_needs: parsed.client_needs || [],
  objectives: parsed.objectives || [],
  constraints: parsed.constraints || [],
  style_preferences: parsed.style_preferences || {},
  rooms_affected: parsed.rooms_affected || [],
  missing_info: parsed.missing_info || [],
  open_questions: parsed.open_questions || []
} }];

const parsed = $('Parse Briefing Response').first().json;
const savedBriefing = $('Save Briefing').first().json;
const approvalRecord = $('Create Approval').first().json;
const resumeUrl = $execution.resumeUrl;
const webhookToken = approvalRecord.webhook_token || '';
const approveUrl = resumeUrl + '?action=approve&token=' + encodeURIComponent(webhookToken);
const rejectUrl = resumeUrl + '?action=reject&token=' + encodeURIComponent(webhookToken);
const needsList = (parsed.client_needs || []).map(function(n) {
  const text = typeof n === 'object' && n !== null ? (n.need || JSON.stringify(n)) : String(n);
  return '<li>' + text + '</li>';
}).join('');
const objList = (parsed.objectives || []).map(function(o) { return '<li>' + String(o) + '</li>'; }).join('');
const missingList = (parsed.missing_info || []).map(function(m) { return '<li>' + String(m) + '</li>'; }).join('');
const htmlBody = '<div style="font-family:Arial,sans-serif;max-width:700px;margin:0 auto">'
  + '<h2 style="color:#2c3e50">Studio AI - Revision de Briefing</h2>'
  + '<h3 style="color:#7f8c8d">Proyecto: ' + parsed.project_name + '</h3>'
  + '<p><b>Cliente:</b> ' + parsed.client_name + ' &nbsp;|&nbsp; <b>Version:</b> ' + parsed.next_version + '</p>'
  + '<hr style="border:none;border-top:1px solid #eee">'
  + '<h4>Resumen:</h4><p>' + parsed.summary + '</p>'
  + '<h4>Necesidades del cliente:</h4><ul>' + needsList + '</ul>'
  + '<h4>Objetivos:</h4><ul>' + objList + '</ul>'
  + '<h4>Informacion faltante:</h4><ul>' + missingList + '</ul>'
  + '<div style="margin:32px 0;text-align:center">'
  + '<a href="' + approveUrl + '" style="background:#27ae60;color:white;padding:14px 28px;text-decoration:none;border-radius:4px;margin-right:16px;display:inline-block;font-size:15px">Aprobar Briefing</a>'
  + '<a href="' + rejectUrl + '" style="background:#e74c3c;color:white;padding:14px 28px;text-decoration:none;border-radius:4px;display:inline-block;font-size:15px">Solicitar Revision</a>'
  + '</div>'
  + '<p style="color:#95a5a6;font-size:12px;text-align:center">Este enlace expira en 72 horas.</p>'
  + '</div>';
const archEmail = ($('Load Architect Email').first()?.json?.value) || 'botelladesdeel98@gmail.com';
return [{ json: {
  to: archEmail,
  subject: '[Studio AI] Briefing para revision: ' + parsed.project_name,
  html_body: htmlBody,
  briefing_id: savedBriefing.id,
  approval_id: approvalRecord.id,
  project_id: parsed.project_id,
  project_name: parsed.project_name,
  next_version: parsed.next_version
} }];

const resumeData = $input.first().json;
const emailData = $('Build Approval Email').first().json;
const approvalRecord = $('Create Approval').first().json;
const expectedToken = approvalRecord.webhook_token || '';
const receivedToken = (resumeData.query && resumeData.query.token)
  || (resumeData.body && resumeData.body.token)
  || resumeData.token
  || '';
const tokenValid = !!expectedToken && receivedToken === expectedToken;
let action = 'reject';
if (tokenValid) {
  action = (resumeData.query && resumeData.query.action)
    || (resumeData.body && resumeData.body.action)
    || resumeData.action
    || 'reject';
}
return [{ json: {
  action: action,
  is_approved: action === 'approve',
  project_id: emailData.project_id,
  briefing_id: emailData.briefing_id,
  approval_id: emailData.approval_id,
  project_name: emailData.project_name,
  next_version: emailData.next_version
} }];

const parsed = $input.first().json;
const project = $('Load Project + Client').first().json;
const keyFields = {
  rooms_affected: parsed.rooms_affected || [],
  constraints: parsed.constraints || [],
  project_type: project.project_type || '',
  property_area_m2: project.property_area_m2 || null,
  budget_target: project.budget_target || null
};
const content = JSON.stringify(keyFields);
let hash = 5381;
for (let i = 0; i < content.length; i++) {
  hash = ((hash << 5) + hash) + content.charCodeAt(i);
  hash = hash & hash;
}
const newHash = Math.abs(hash).toString(16);
const existingHash = project.briefing_hash || '';
const scopeCreep = existingHash !== '' && existingHash !== newHash;
return [{ json: { ...parsed, new_hash: newHash, scope_creep_detected: scopeCreep } }];

const project = $('Load Project + Client').first().json;
const metadata = project.metadata || {};
const notes = metadata.architect_intake_notes || metadata.notes || '';
return [{ json: {
  project_type: project.project_type,
  location_zone: project.location_province || project.location_city || 'desconocido',
  property_type: project.property_type || 'no especificado',
  area_m2: project.property_area_m2 || null,
  summary: notes.substring(0, 500),
  briefing_summary: notes.substring(0, 1000),
  exclude_project_id: project.id,
  top_k: 3
} }];
